/// </summary>
/// <param name = "_sectionType">NDXBVEmailRequestSectionType</param>
protected void new(NDXBVEmailRequestSectionType _sectionType)
{
    super(_sectionType);

    this.addFields2Section(fieldNum(NDXBVEMailRequestPlaner, Name1), 
        fieldNum(NDXBVEMailRequestPlanerAIDecisionBasis, Name1AIDB),
        fieldNum(NDXBVEMailRequestPlanerAIInfo, Name1AII));
    this.addFields2Section(fieldNum(NDXBVEMailRequestPlaner, Name2), 
        fieldNum(NDXBVEMailRequestPlanerAIDecisionBasis, Name2AIDB),
        fieldNum(NDXBVEMailRequestPlanerAIInfo, Name2AII));
    this.addFields2Section(fieldNum(NDXBVEMailRequestPlaner, Name3), 
        fieldNum(NDXBVEMailRequestPlanerAIDecisionBasis, Name3AIDB),
        fieldNum(NDXBVEMailRequestPlanerAIInfo, Name3AII));
    this.addFields2Section(fieldNum(NDXBVEMailRequestPlaner, AddressStreet), 
        fieldNum(NDXBVEMailRequestPlanerAIDecisionBasis, AddressStreetAIDB),
        fieldNum(NDXBVEMailRequestPlanerAIInfo, AddressStreetAII));
    this.addFields2Section(fieldNum(NDXBVEMailRequestPlaner, AddressZipCode), 
        fieldNum(NDXBVEMailRequestPlanerAIDecisionBasis, AddressZipCodeAIDB),
        fieldNum(NDXBVEMailRequestPlanerAIInfo, AddressZipCodeAII));
    this.addFields2Section(fieldNum(NDXBVEMailRequestPlaner, AddressCity), 
        fieldNum(NDXBVEMailRequestPlanerAIDecisionBasis, AddressCityAIDB),
        fieldNum(NDXBVEMailRequestPlanerAIInfo, AddressCityAII));
    this.addFields2Section(fieldNum(NDXBVEMailRequestPlaner, AddressCountryRegionIdISOCode), 
        fieldNum(NDXBVEMailRequestPlanerAIDecisionBasis, AddressCountryRegionIdISOCodeAIDB),
        fieldNum(NDXBVEMailRequestPlanerAIInfo, AddressCountryRegionIdISOCodeAII));
    this.addFields2Section(fieldNum(NDXBVEMailRequestPlaner, Phone), 
        fieldNum(NDXBVEMailRequestPlanerAIDecisionBasis, PhoneAIDB),
        fieldNum(NDXBVEMailRequestPlanerAIInfo, PhoneAII));
}

/// <summary>
/// PaffH 10.11.25
/// last modified: PaffH 25.11.25
/// </summary>
/// <param name = "_fieldIdAiField">FieldId</param>
/// <param name = "_fieldIdaiFieldDecisionBase">FieldId</param>
/// <param name = "_fieldIdaiFieldInfo">FieldId</param>
private void addFields2Section(FieldId _fieldIdAiField, FieldId _fieldIdaiFieldDecisionBase, FieldId _fieldIdAiFieldInfo)
{
    NDXBVEMailRequestPlaner nDXBVEMailRequestPlaner;
    NDXBVEMailRequestPlanerAIDecisionBasis nDXBVEMailRequestPlanerAIDecisionBasis;
    NDXBVEMailRequestPlanerAIInfo nDXBVEMailRequestPlanerAIInfo;

    NDXBVEmailRequestAIDBFieldContract aiField = NDXBVEmailRequestAIDBFieldContract::constructFromCommon(nDXBVEMailRequestPlaner, _fieldIdAiField);
    NDXBVEmailRequestAIDBFieldDecisionBaseContract aiFieldDecisionBase = NDXBVEmailRequestAIDBFieldDecisionBaseContract::constructFromCommon(nDXBVEMailRequestPlanerAIDecisionBasis, _fieldIdaiFieldDecisionBase);
    NDXBVEmailRequestAIDBFieldInfoContract aiFieldInfo = NDXBVEmailRequestAIDBFieldInfoContract::constructFromCommon(nDXBVEMailRequestPlanerAIInfo, _fieldIdAiFieldInfo);
    sectionGroups.addEnd(NDXBVEmailRequestAIDBSectionGroupContract::construct(aiField, aiFieldDecisionBase, aiFieldInfo));
}

/// <summary>
/// PaffH 10.11.25
